import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeJobs } from './lib.mjs';

test('drops invalid jobs and preserves valid order and duplicate ids regardless of priority', () => {
  const jobs = [
    { id: 'same', duration: 3, priority: -1 },
    null,
    undefined,
    7,
    'job',
    {},
    { id: '', duration: 1 },
    { id: 7, duration: 1 },
    { id: 'bad', duration: 0 },
    { id: 'bad', duration: -2 },
    { id: 'bad', duration: 1.5 },
    { id: 'bad', duration: '2' },
    { id: 'bad', duration: NaN },
    { id: 'bad', duration: Infinity },
    { id: 'bad', duration: true },
    { id: 'same', duration: 1, priority: 100 },
    { id: ' ', duration: 2 },
  ];

  assert.deepEqual(normalizeJobs(jobs), [
    { id: 'same', duration: 3 },
    { id: 'same', duration: 1 },
    { id: ' ', duration: 2 },
  ]);
});

test('returns fresh objects and leaves the input untouched', () => {
  const first = Object.freeze({ id: 'a', duration: 2, priority: 10 });
  const invalid = Object.freeze({ id: '', duration: 1 });
  const jobs = Object.freeze([first, invalid, first]);
  const result = normalizeJobs(jobs);

  assert.notStrictEqual(result, jobs);
  assert.notStrictEqual(result[0], first);
  assert.notStrictEqual(result[0], result[1]);
  result[0].duration = 99;
  assert.equal(result[1].duration, 2);
  assert.deepEqual(jobs, [
    { id: 'a', duration: 2, priority: 10 },
    { id: '', duration: 1 },
    { id: 'a', duration: 2, priority: 10 },
  ]);
});

test('returns an empty array for empty input', () => {
  assert.deepEqual(normalizeJobs([]), []);
});

