import test from 'node:test';
import assert from 'node:assert/strict';
import { normalizeJobs, scheduleJobs } from './lib.mjs';

test('matches the final acceptance example, including initial and later ties', () => {
  assert.deepEqual(scheduleJobs([
    { id: 'a', duration: 3 },
    { id: 'b', duration: 1 },
    { id: 'c', duration: 2 },
    { id: 'd', duration: 1 },
  ]), [
    { id: 'a', start: 0, end: 3, slot: 0 },
    { id: 'b', start: 0, end: 1, slot: 1 },
    { id: 'c', start: 1, end: 3, slot: 1 },
    { id: 'd', start: 3, end: 4, slot: 0 },
  ]);
});

test('reuses the earliest slot and ignores priorities while preserving duplicate ids', () => {
  const first = Object.freeze({ id: 'same', duration: 5, priority: -1 });
  const second = Object.freeze({ id: 'same', duration: 1, priority: 100 });
  const third = Object.freeze({ id: 'third', duration: 1, priority: 200 });
  const jobs = Object.freeze([first, second, third, second]);
  const before = structuredClone(jobs);
  const result = scheduleJobs(jobs);

  assert.deepEqual(result, [
    { id: 'same', start: 0, end: 5, slot: 0 },
    { id: 'same', start: 0, end: 1, slot: 1 },
    { id: 'third', start: 1, end: 2, slot: 1 },
    { id: 'same', start: 2, end: 3, slot: 1 },
  ]);
  assert.notStrictEqual(result, jobs);
  assert.notStrictEqual(result[0], first);
  assert.notStrictEqual(result[1], result[3]);
  result[1].id = 'changed';
  assert.equal(result[3].id, 'same');
  assert.deepEqual(jobs, before);
});

test('schedules normalized jobs with invalid entries removed and ids untrimmed', () => {
  assert.deepEqual(scheduleJobs(normalizeJobs([
    { id: '', duration: 2 },
    { id: ' ', duration: 2, priority: 100 },
    { id: 'a', duration: 0 },
    { id: 'a', duration: 3, priority: -1 },
  ])), [
    { id: ' ', start: 0, end: 2, slot: 0 },
    { id: 'a', start: 0, end: 3, slot: 1 },
  ]);
});

test('handles empty and single-job inputs and resets availability for each call', () => {
  assert.deepEqual(scheduleJobs([]), []);
  const jobs = [{ id: 'a', duration: 2 }];
  const expected = [{ id: 'a', start: 0, end: 2, slot: 0 }];
  assert.deepEqual(scheduleJobs(jobs), expected);
  assert.deepEqual(scheduleJobs(jobs), expected);
});

