/** Return fresh valid jobs in input order, ignoring all other fields. */
export function normalizeJobs(jobs) {
  const normalized = [];
  for (const job of jobs) {
    if (job == null) continue;
    const { id, duration } = job;
    if (typeof id === 'string' && id.length > 0 &&
        Number.isInteger(duration) && duration > 0) {
      normalized.push({ id, duration });
    }
  }
  return normalized;
}

