import test from 'node:test';
import { normalizeJobs } from './lib.mjs';

test('drops invalid jobs without coercion or trimming nonempty ids', () => {
  const jobs = [
    null, undefined, false, 4, 'job', {},
    { id: '', duration: 1 },
    { id: 1, duration: 1 },
    { id: new String('boxed'), duration: 1 },
    { id: 'missing' },
    { id: 'zero', duration: 0 },
    { id: 'negative', duration: -1 },
    { id: 'fractional', duration: 1.5 },
    { id: 'string', duration: '2' },
    { id: 'boolean', duration: true },
    { id: 'nan', duration: NaN },
    { id: 'infinite', duration: Infinity },
    { id: 'bigint', duration: 2n },
    { id: 'valid', duration: 2 },
    { id: ' ', duration: 1 },
  ];
  assert.deepEqual(normalizeJobs(jobs), [
    { id: 'valid', duration: 2 },
    { id: ' ', duration: 1 },
  ]);
});

test('preserves input order and duplicate ids regardless of priority', () => {
  assert.deepEqual(normalizeJobs([
    { id: 'z', duration: 3, priority: -100 },
    { id: '', duration: 5, priority: 1000 },
    { id: 'a', duration: 1, priority: 100 },
    { id: 'z', duration: 2, priority: 0 },
  ]), [
    { id: 'z', duration: 3 },
    { id: 'a', duration: 1 },
    { id: 'z', duration: 2 },
  ]);
});

test('returns fresh objects and leaves frozen input unchanged', () => {
  const job = Object.freeze({
    id: 'same', duration: 2, extra: 'ignored',
    get priority() { throw new Error('priority must not be read'); },
  });
  const jobs = Object.freeze([job, job]);
  const result = normalizeJobs(jobs);
  assert.deepEqual(result, [
    { id: 'same', duration: 2 },
    { id: 'same', duration: 2 },
  ]);
  assert.notStrictEqual(result, jobs);
  assert.notStrictEqual(result[0], job);
  assert.notStrictEqual(result[1], job);
  assert.notStrictEqual(result[0], result[1]);
  result[0].id = 'changed';
  result[0].duration = 99;
  assert.equal(job.id, 'same');
  assert.equal(job.duration, 2);
  assert.equal(job.extra, 'ignored');
  assert.equal(result[1].id, 'same');
});

test('empty input returns a new empty array', () => {
  const jobs = [];
  const result = normalizeJobs(jobs);
  assert.deepEqual(result, []);
  assert.notStrictEqual(result, jobs);
});

