import assert from 'node:assert/strict';
import test from 'node:test';
import { encodeCell } from './lib.mjs';

test('empty and ordinary values use the required string conversion', () => {
  for (const [value, expected] of [
    [null, ''], [undefined, ''], ['', ''], ['plain', 'plain'],
    [0, '0'], [false, 'false'], [42n, '42'], [Symbol('cell'), 'Symbol(cell)'],
    [' a\tb ', ' a\tb '],
    [{ toString: () => 'custom,value' }, '"custom,value"'],
  ]) {
    assert.equal(encodeCell(value), expected);
  }
});

test('comma, quote, CR, and LF require quotes and embedded quotes double', () => {
  for (const [value, expected] of [
    ['a,b', '"a,b"'], ['a"b', '"a""b"'], ['"', '""""'],
    ['a\rb', '"a\rb"'], ['a\nb', '"a\nb"'], ['a\r\nb', '"a\r\nb"'],
    ['a,"b"\r\nc', '"a,""b""\r\nc"'],
  ]) {
    assert.equal(encodeCell(value), expected);
  }
});

