import assert from 'node:assert/strict';
import test from 'node:test';
import { readFileSync } from 'node:fs';
import { encodeCell, encodeTable } from './lib.mjs';

test('empty and ordinary values use the required string conversion', () => {
  for (const [value, expected] of [
    [null, ''], [undefined, ''], ['', ''], ['plain', 'plain'],
    [0, '0'], [false, 'false'], [42n, '42'], [Symbol('cell'), 'Symbol(cell)'],
    [' a\tb ', ' a\tb '],
    [{ toString: () => 'custom,value' }, '"custom,value"'],
  ]) {
    assert.equal(encodeCell(value), expected);
  }
});

test('comma, quote, CR, and LF require quotes and embedded quotes double', () => {
  for (const [value, expected] of [
    ['a,b', '"a,b"'], ['a"b', '"a""b"'], ['"', '""""'],
    ['a\rb', '"a\rb"'], ['a\nb', '"a\nb"'], ['a\r\nb', '"a\r\nb"'],
    ['a,"b"\r\nc', '"a,""b""\r\nc"'],
  ]) {
    assert.equal(encodeCell(value), expected);
  }
});

test('tables use comma cells and CRLF records with no appended newline', () => {
  assert.equal(encodeTable([['a', 'b'], [0, false], [null, undefined]]),
    'a,b\r\n0,false\r\n,');
  assert.equal(encodeTable([['single']]), 'single');
});

test('empty tables and rows preserve the number of records', () => {
  for (const [rows, expected] of [
    [[], ''], [[[]], ''], [[[], []], '\r\n'],
    [[[], [], []], '\r\n\r\n'],
    [[[], ['x']], '\r\nx'], [[['x'], []], 'x\r\n'],
    [[[null, undefined, '']], ',,'],
  ]) {
    assert.equal(encodeTable(rows), expected);
  }
});

test('tables escape mixed cells while preserving cell CR and LF', () => {
  assert.equal(encodeTable([
    ['a,b', 'a"b', 'a\rb', 'a\nb', 'a\r\nb'],
    ['plain', 42n, null, undefined, ' a\tb '],
  ]), '"a,b","a""b","a\rb","a\nb","a\r\nb"\r\nplain,42,,, a\tb ');
});

test('encoding accepts frozen rows without mutating the input', () => {
  const rows = Object.freeze([
    Object.freeze(['a,b', null]),
    Object.freeze([]),
    Object.freeze(['x', 1]),
  ]);
  const before = structuredClone(rows);
  assert.equal(encodeTable(rows), '"a,b",\r\n\r\nx,1');
  assert.deepEqual(rows, before);
});

test('recovery report records the final contract and deferred feature', () => {
  const recovery = JSON.parse(readFileSync(new URL('./recovery.json', import.meta.url), 'utf8'));
  assert.deepEqual(recovery, {
    contract: { separator: ',', newline: 'CRLF', nullValue: '', trailingNewline: false },
    deferred: ['CSV_IMPORT'],
    completed: ['encodeCell', 'encodeTable'],
    unresolved: [],
  });
});

