const delimiter = ',';

export function encodeCell(value) {
  const cell = value == null ? '' : String(value);
  if (cell.includes(delimiter) || /["\r\n]/.test(cell)) {
    return `"${cell.replaceAll('"', '""')}"`;
  }
  return cell;
}

