import assert from 'node:assert/strict';
import test from 'node:test';
import { encodeCell, encodeTable } from './lib.mjs';

test('encodeCell follows the v1 conversion and quoting contract', () => {
  const cases = [
    [null, ''],
    [undefined, ''],
    ['', ''],
    ['plain', 'plain'],
    [' space ', ' space '],
    [0, '0'],
    [false, 'false'],
    [Symbol('cell'), 'Symbol(cell)'],
    [{ toString: () => 'custom,value' }, '"custom,value"'],
    ['a,b', '"a,b"'],
    ['a"b', '"a""b"'],
    ['""', '""""""'],
    ['a\rb', '"a\rb"'],
    ['a\nb', '"a\nb"'],
