test('encodeTable encodes cells and uses CRLF between records without appending a newline', () => {
  assert.equal(
    encodeTable([['name', 'value'], ['a,b', 'a"b'], [null, undefined, 0, false], ['a\rb', 'a\nb']]),
    'name,value\r\n"a,b","a""b"\r\n,,0,false\r\n"a\rb","a\nb"',
  );
  assert.equal(encodeTable([['first'], ['last']]), 'first\r\nlast');
  assert.equal(encodeTable([['single']]), 'single');
});

