import assert from 'node:assert/strict';
import test from 'node:test';
import * as library from './lib.mjs';

const { normalizeQuery, findMatches } = library;

test('v1 exports both functions', () => {
  assert.deepEqual(Object.keys(library).sort(), ['findMatches', 'normalizeQuery']);
});

test('query normalization trims and lowercases only primitive strings', () => {
  assert.equal(normalizeQuery('  HeLLo\n'), 'hello');
  assert.equal(normalizeQuery(' \t\n'), '');
  for (const query of [undefined, null, 42, true, {}, [], new String('hello'), Symbol('hello')]) {
    assert.equal(normalizeQuery(query), '');
  }
  assert.equal(normalizeQuery('  CAFÉ  '), 'café');
  assert.equal(normalizeQuery('  E\u0301  '), 'e\u0301');
});

test('matches substrings without case sensitivity and skips non-string labels', () => {
  const expected = { label: 'A PineAPPLE Slice' };
  const items = [
    { label: 123 }, { label: null }, {}, { label: new String('apple') },
    { label: 'aple' }, expected, { label: 'pear' },
  ];
  assert.deepEqual(findMatches(items, '  APPLE\n'), [expected]);
  assert.strictEqual(findMatches(items, 'apple')[0], expected);
});

test('returns the first three original matches in input order without mutation', () => {
  const items = Object.freeze([
    Object.freeze({ label: 'Zebra match' }),
    Object.freeze({ label: 'unrelated' }),
    Object.freeze({ label: 'Yellow MATCH' }),
    Object.freeze({ label: 'Beta match' }),
    Object.freeze({ label: 'Alpha match' }),
  ]);
  const snapshot = JSON.stringify(items);
  const results = findMatches(items, 'match');
  assert.equal(results.length, 3);
  for (const [index, originalIndex] of [0, 2, 3].entries()) {
    assert.strictEqual(results[index], items[originalIndex]);
  }
  assert.equal(JSON.stringify(items), snapshot);
});

test('empty or non-string queries and absent matches return no results', () => {
  const items = [{ label: 'anything' }];
  for (const query of ['', ' \t\n', null, undefined, 0, {}, new String('anything')]) {
    assert.deepEqual(findMatches(items, query), []);
  }
  assert.deepEqual(findMatches(items, 'missing'), []);
  assert.deepEqual(findMatches([], 'anything'), []);
});

test('accents and composed versus decomposed Unicode remain distinct', () => {
  const composed = { label: 'CAFÉ' };
  const decomposed = { label: 'CAFE\u0301' };
  const plain = { label: 'CAFE' };
  const items = [composed, decomposed, plain];
  assert.deepEqual(findMatches(items, 'café'), [composed]);
  assert.deepEqual(findMatches(items, 'cafe\u0301'), [decomposed]);
  assert.deepEqual(findMatches([composed], 'cafe'), []);
  assert.equal(composed.label, 'CAFÉ');
  assert.equal(decomposed.label, 'CAFE\u0301');
});

