  ];
  const matches = findMatches(items, ' \tCaT\n');
  assert.equal(matches.length, 3);
  assert.strictEqual(matches[0], items[0]);
  assert.strictEqual(matches[1], items[2]);
  assert.strictEqual(matches[2], items[3]);
});

test('skips missing and non-string labels without coercion or counting them', () => {
  const uncoercible = { toString() { throw new Error('Must not coerce labels'); } };
  const match = { label: 'needle' };
  const items = [null, undefined, {}, { label: null }, { label: 12 },
    { label: false }, { label: uncoercible }, { label: new String('needle') }, match];
  assert.deepEqual(findMatches(items, 'needle'), [match]);
  assert.strictEqual(findMatches(items, 'needle')[0], match);
});

