export function normalizeJobs(jobs) {
  const normalized = [];

  for (const job of jobs) {
    if (
      job !== null &&
      typeof job === 'object' &&
      typeof job.id === 'string' &&
      job.id.length > 0 &&
      Number.isInteger(job.duration) &&
      job.duration > 0
    ) {
      normalized.push({ id: job.id, duration: job.duration });
    }
  }

  return normalized;
}

export function scheduleJobs(jobs) {
  const available = [0, 0, 0];
  const scheduled = [];

  for (const job of normalizeJobs(jobs)) {
    let slot = 0;
    for (let candidate = 1; candidate < available.length; candidate++) {
      if (available[candidate] < available[slot]) {
        slot = candidate;
      }
    }

    const start = available[slot];
    const end = start + job.duration;
    scheduled.push({ id: job.id, start, end, slot });
    available[slot] = end;
  }

  return scheduled;
}

