test('schedules empty input and starts the first three jobs at zero in slots 0, 1, 2', () => {
  assert.deepEqual(scheduleJobs([]), []);
  assert.deepEqual(scheduleJobs([
    { id: 'a', duration: 4 },
    { id: 'b', duration: 2 },
    { id: 'c', duration: 3 },
  ]), [
    { id: 'a', start: 0, end: 4, slot: 0 },
    { id: 'b', start: 0, end: 2, slot: 1 },
    { id: 'c', start: 0, end: 3, slot: 2 },
  ]);
});

test('reuses the earliest available slot and accumulates start and end times', () => {
  assert.deepEqual(scheduleJobs([
    { id: 'a', duration: 5 },
    { id: 'b', duration: 2 },
    { id: 'c', duration: 3 },
    { id: 'd', duration: 2 },
    { id: 'e', duration: 5 },
    { id: 'f', duration: 2 },
    { id: 'g', duration: 1 },
  ]), [
    { id: 'a', start: 0, end: 5, slot: 0 },
    { id: 'b', start: 0, end: 2, slot: 1 },
    { id: 'c', start: 0, end: 3, slot: 2 },
    { id: 'd', start: 2, end: 4, slot: 1 },
    { id: 'e', start: 3, end: 8, slot: 2 },
    { id: 'f', start: 4, end: 6, slot: 1 },
    { id: 'g', start: 5, end: 6, slot: 0 },
  ]);
});

test('breaks later ties by the lowest slot index', () => {
  assert.deepEqual(scheduleJobs([
    { id: 'a', duration: 2 },
    { id: 'b', duration: 2 },
    { id: 'c', duration: 2 },
    { id: 'd', duration: 1 },
    { id: 'e', duration: 1 },
    { id: 'f', duration: 1 },
    { id: 'g', duration: 1 },
  ]), [
    { id: 'a', start: 0, end: 2, slot: 0 },
    { id: 'b', start: 0, end: 2, slot: 1 },
    { id: 'c', start: 0, end: 2, slot: 2 },
    { id: 'd', start: 2, end: 3, slot: 0 },
    { id: 'e', start: 2, end: 3, slot: 1 },
    { id: 'f', start: 2, end: 3, slot: 2 },
    { id: 'g', start: 3, end: 4, slot: 0 },
  ]);
});

test('preserves order and duplicates without reading priority or mutating jobs', () => {
  const job = Object.freeze({
    id: 'same', duration: 2,
    get priority() { throw new Error('priority must be ignored'); },
  });
  const jobs = Object.freeze([
    job,
    Object.freeze({ id: 'next', duration: 1, priority: 100 }),
    job,
    Object.freeze({ id: ' ', duration: 1, priority: -100 }),
  ]);
  const result = scheduleJobs(jobs);
  assert.deepEqual(result, [
    { id: 'same', start: 0, end: 2, slot: 0 },
    { id: 'next', start: 0, end: 1, slot: 1 },
    { id: 'same', start: 0, end: 2, slot: 2 },
    { id: ' ', start: 1, end: 2, slot: 1 },
  ]);
  assert.notStrictEqual(result, jobs);
  assert.notStrictEqual(result[0], job);
  assert.notStrictEqual(result[0], result[2]);
  result[0].id = 'changed';
  assert.equal(job.id, 'same');
  assert.equal(result[2].id, 'same');
  assert.equal(jobs[0], job);
  assert.equal(jobs[2], job);
});

test('normalization and scheduling satisfy the complete v1 contract', () => {
  const jobs = Object.freeze([
    Object.freeze({ id: 'first', duration: 2, priority: -100 }),
    null,
    Object.freeze({ id: '', duration: 1 }),
    Object.freeze({ id: 'duplicate', duration: 1, priority: 100 }),
    Object.freeze({ id: 'duplicate', duration: 3 }),
    Object.freeze({ id: ' ', duration: 2 }),
  ]);
  assert.deepEqual(scheduleJobs(normalizeJobs(jobs)), [
    { id: 'first', start: 0, end: 2, slot: 0 },
    { id: 'duplicate', start: 0, end: 1, slot: 1 },
    { id: 'duplicate', start: 0, end: 3, slot: 2 },
    { id: ' ', start: 1, end: 3, slot: 1 },
  ]);
});

