  const cell = value === null || value === undefined ? '' : String(value);
  return /[\t"\r\n]/.test(cell) ? `"${cell.replaceAll('"', '""')}"` : cell;
}

export function encodeTable(rows) {
  return rows.map(row => row.map(encodeCell).join('\t')).join('\r\n');
