import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import test from 'node:test';
import * as queryModule from './lib.mjs';

const { normalizeQuery, findMatches } = queryModule;

test('normalizeQuery trims and lowercases primitive strings only', () => {
  assert.equal(normalizeQuery(' \tMiXeD\n'), 'mixed');
  assert.equal(normalizeQuery(' \n\t '), '');
  for (const query of [undefined, null, 0, true, {}, [], new String('MATCH'), Symbol('match')]) {
    assert.equal(normalizeQuery(query), '');
  }
});

test('matching preserves input order, original objects and the two-result limit', () => {
  const items = Object.freeze([
    Object.freeze({ label: 'Zebra MATCH', id: 1 }),
    Object.freeze({ label: 'unrelated', id: 2 }),
    Object.freeze({ label: 'Alpha match', id: 3 }),
    Object.freeze({ label: 'Beta MATCH', id: 4 }),
  ]);
  const snapshot = structuredClone(items);
  const matches = findMatches(items, ' \tMaTcH\n');
  assert.deepEqual(matches, [items[0], items[2]]);
  assert.strictEqual(matches[0], items[0]);
  assert.strictEqual(matches[1], items[2]);
  assert.notStrictEqual(matches, items);
  assert.deepEqual(items, snapshot);
});

test('matching skips non-string labels and handles zero or one match', () => {
  const match = { label: 'a needle b' };
  const items = [{}, { label: 123 }, { label: false }, { label: null },
    { label: new String('needle') }, { label: 'unrelated' }, match];
  assert.deepEqual(findMatches(items, 'needle'), [match]);
  assert.deepEqual(findMatches(items, 'missing'), []);
  assert.deepEqual(findMatches([], 'needle'), []);
});

test('empty normalized queries produce no results', () => {
  const items = [{ label: 'anything' }, { label: '' }];
  for (const query of ['', ' \t\n ', undefined, null, 123, {}, new String('anything')]) {
    assert.deepEqual(findMatches(items, query), []);
  }
});

test('accents and composed versus decomposed Unicode remain distinct', () => {
  assert.equal(normalizeQuery(' CAF\u00c9 '), 'caf\u00e9');
  assert.equal(normalizeQuery(' CAFE\u0301 '), 'cafe\u0301');
  const accented = { label: 'CAF\u00c9' };
  const decomposed = { label: 'CAFE\u0301' };
  assert.deepEqual(findMatches([accented], 'cafe'), []);
  assert.deepEqual(findMatches([accented, decomposed], 'caf\u00e9'), [accented]);
  assert.deepEqual(findMatches([accented, decomposed], 'cafe\u0301'), [decomposed]);
});

test('matching uses literal substrings without fuzzy search', () => {
  const literal = { label: 'prefix a.b suffix' };
  assert.deepEqual(findMatches([{ label: 'axb' }, literal], 'a.b'), [literal]);
  assert.deepEqual(findMatches([{ label: 'needle' }], 'nedle'), []);
  assert.deepEqual(Object.keys(queryModule).sort(), ['findMatches', 'normalizeQuery']);
});

test('recovery manifest records the final contract, deferred feature and uncertainty', async () => {
  const recovery = JSON.parse(await readFile(new URL('./recovery.json', import.meta.url), 'utf8'));
  assert.deepEqual(Object.keys(recovery).sort(), ['completed', 'contract', 'deferred', 'unresolved']);
  assert.deepEqual(recovery.contract, {
    limit: 2, order: 'input', query: 'trim-lowercase', empty: 'no-results',
  });
  assert.deepEqual(recovery.deferred, ['FUZZY_SEARCH']);
  assert.deepEqual(recovery.completed, ['normalizeQuery', 'findMatches']);
  assert.equal(recovery.unresolved.length, 1);
  assert.match(recovery.unresolved[0], /do not specify behavior for invalid items containers or null entries/);
});

