  assert.equal(lib.normalizeQuery('  HeLLo \n'), 'hello');
  assert.equal(lib.normalizeQuery(' CAFÉ '), 'café');
  assert.equal(lib.normalizeQuery(' CAFE\u0301 '), 'cafe\u0301');
